    };
    let mut values = Vec::new();
    for method in ["GetDescription", "GetAuthorCredit", "GetChartName"] {
        if let Some(text) = call_string_method(steps, method)?
            && !text.is_empty()
            && !values.iter().any(|value| value == &text)
