        let lua = Lua::new();
        let table = lua.create_table().unwrap();
        table.raw_set(1, "a").unwrap();
        table.raw_set(2, "b").unwrap();
        table.raw_set(3, "c").unwrap();

        let mut args = MultiValue::new();
        args.push_back(Value::Table(table));
        args.push_back(Value::Integer(1));

