        fs::create_dir_all(&dir).unwrap();
        let entry = dir.join("default.lua");
        fs::write(&entry, r#"
UPDATES = {}
return Def.ActorFrame { InitCommand = function(self)
    self:SetUpdateFunction(function(_, delta)
        UPDATES[#UPDATES+1] = { delta, GAMESTATE:GetCurMusicSeconds() }
