                music_seconds: seconds, screen_seconds: seconds, beat: seconds * 2.0,
                delta_seconds: seconds - previous, chart_attacks: Some(schedule.clone()),
                ..Default::default()
            }).unwrap();
            assert!(output.errors.is_empty(), "{:?}", output.errors);
            previous = seconds;
