    end,
    PeakNPSUpdatedMessageCommand=function(self)
        MESSAGEMAN:Broadcast('AuthoredPeakReaction')
    end,
    AuthoredRuntimeCommand=function(self)
        MESSAGEMAN:Broadcast('CurrentSongChanged')
        MESSAGEMAN:Broadcast('PeakNPSUpdated')
