                    assert_eq!(parts[index].get::<Function>("GetX").unwrap().call::<f32>(parts[index].clone()).unwrap(), x);
                    assert_eq!(parts[index].get::<Function>("GetZoomedWidth").unwrap().call::<f32>(parts[index].clone()).unwrap(), width);
                }
