            &entry,
            r#"
return Def.ActorFrame{
    OnCommand=function(self)
        local player = SCREENMAN:GetTopScreen():GetChild("PlayerP1")
        self:SetUpdateFunction(function()
            local beat = GAMESTATE:GetSongBeat()
