        for beat in [0.5, 1.0, 2.0] {
            assert!(x.samples.iter().any(|sample| (sample.time - beat).abs() < 1e-5 && matches!(sample.value, SongLuaOverlayUpdateValue::F32(value) if (value - beat * 10.0).abs() < 1e-4)), "missing draw state at beat {beat}");
        }
